import java.util.*;
import java.io.*;

public class Main {
    static final int INF_VAL = 1000000000;
    static final int MAX_SIZE = 11;
    static final int MAX_NODES = 205;
    static final int DIRECTIONS_COUNT = 4;
    static final int[] delta_y = {-1, 0, 1, 0};
    static final int[] delta_x = {0, -1, 0, 1};

    static int size_n, max_t;
    static char[][] grid = new char[MAX_SIZE][MAX_SIZE];
    static char[][] backup = new char[MAX_SIZE][MAX_SIZE];
    static int start_r, start_c;
    static int[][] dist_bum = new int[MAX_SIZE][MAX_SIZE];
    static int[][] dist_map = new int[MAX_SIZE][MAX_SIZE];
    static boolean[][] reach = new boolean[MAX_SIZE][MAX_SIZE];
    static int total_vertices;
    static int[][] cap = new int[MAX_SIZE][MAX_SIZE];
    static List<Integer>[] adj_list = new ArrayList[MAX_NODES];
    static int[] flow_arr = new int[MAX_NODES];
    static int[] parent_arr = new int[MAX_NODES];

    static class Coord {
        int first, second;
        Coord(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static void first_bfs() {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(cap[i], 0);
        }
        cap[start_r][start_c] = max_t;
        Queue<Coord> q = new LinkedList<>();
        q.offer(new Coord(start_r, start_c));
        while (!q.isEmpty()) {
            Coord v = q.poll();
            int d = cap[v.first][v.second];
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int u_r = v.first + delta_y[dir];
                int u_c = v.second + delta_x[dir];
                if (0 <= u_r && u_r < size_n && 0 <= u_c && u_c < size_n && grid[u_r][u_c] != 'Y' && d + 1 < cap[u_r][u_c]) {
                    cap[u_r][u_c] = d + 1;
                    q.offer(new Coord(u_r, u_c));
                }
            }
        }
    }

    static void second_bfs(int sr, int sc) {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(dist_map[i], INF_VAL);
        }
        dist_map[sr][sc] = 0;
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(reach[i], false);
        }
        reach[sr][sc] = true;
        Queue<Coord> q = new LinkedList<>();
        q.offer(new Coord(sr, sc));
        while (!q.isEmpty()) {
            Coord v = q.poll();
            int d = dist_map[v.first][v.second];
            reach[v.first][v.second] = d <= cap[v.first][v.second];
            if (d >= cap[v.first][v.second]) continue;
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int u_r = v.first + delta_y[dir];
                int u_c = v.second + delta_x[dir];
                if (0 <= u_r && u_r < size_n && 0 <= u_c && u_c < size_n && grid[u_r][u_c] != 'Y' && d + 1 < dist_map[u_r][u_c]) {
                    dist_map[u_r][u_c] = d + 1;
                    q.offer(new Coord(u_r, u_c));
                }
            }
        }
    }

    static void run_bfs(int sr, int sc, int[][] d, int INF_VAL) {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(d[i], INF_VAL);
        }
        d[sr][sc] = 0;
        Queue<Coord> q = new LinkedList<>();
        q.offer(new Coord(sr, sc));
        while (!q.isEmpty()) {
            Coord v = q.poll();
            int d_v = d[v.first][v.second];
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int u_r = v.first + delta_y[dir];
                int u_c = v.second + delta_x[dir];
                if (0 <= u_r && u_r < size_n && 0 <= u_c && u_c < size_n && grid[u_r][u_c] != 'Y' && d_v + 1 < d[u_r][u_c]) {
                    d[u_r][u_c] = d_v + 1;
                    q.offer(new Coord(u_r, u_c));
                }
            }
        }
    }

    static int max_flow() {
        Arrays.fill(flow_arr, 0);
        flow_arr[0] = INF_VAL;
        PriorityQueue<Coord> pq = new PriorityQueue<>((a, b) -> Integer.compare(b.first, a.first));
        pq.offer(new Coord(INF_VAL, 0));
        while (!pq.isEmpty()) {
            Coord top = pq.poll();
            int v = top.second;
            int f = top.first;
            if (flow_arr[v] != f) continue;
            for (int u : adj_list[v]) {
                int minFlow = Math.min(f, cap[v][u]);
                if (minFlow > flow_arr[u]) {
                    flow_arr[u] = minFlow;
                    parent_arr[u] = v;
                    pq.offer(new Coord(flow_arr[u], u));
                }
            }
        }
        int v = total_vertices - 1;
        if (flow_arr[v] == 0) return 0;
        int total_flow = flow_arr[v];
        while (v != 0) {
            int u = parent_arr[v];
            cap[u][v] -= total_flow;
            cap[v][u] += total_flow;
            v = u;
        }
        return total_flow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        size_n = Integer.parseInt(st.nextToken());
        max_t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < size_n; i++) {
            String line = br.readLine();
            for (int j = 0; j < size_n; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'Z') {
                    start_r = i;
                    start_c = j;
                }
            }
        }

        for (int i = 0; i < size_n; i++) {
            String line = br.readLine();
            for (int j = 0; j < size_n; j++) {
                backup[i][j] = line.charAt(j);
            }
        }

        for (int i = 0; i < MAX_NODES; i++) {
            adj_list[i] = new ArrayList<>();
        }

        first_bfs();

        total_vertices = 2 * size_n * size_n + 2;

        for (int i = 0; i < size_n; i++) {
            for (int j = 0; j < size_n; j++) {
                if (Character.isDigit(grid[i][j]) && grid[i][j] > '0') {
                    int v = i * size_n + j + 1;
                    cap[0][v] = grid[i][j] - '0';
                    adj_list[0].add(v);
                    adj_list[v].add(0);
                    second_bfs(i, j);
                    for (int i2 = 0; i2 < size_n; i2++) {
                        for (int j2 = 0; j2 < size_n; j2++) {
                            if (reach[i2][j2] && Character.isDigit(backup[i2][j2]) && backup[i2][j2] > '0') {
                                int u = size_n * size_n + i2 * size_n + j2 + 1;
                                cap[v][u] = MAX_INF;
                                adj_list[v].add(u);
                                adj_list[u].add(v);
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < size_n; i++) {
            for (int j = 0; j < size_n; j++) {
                if (Character.isDigit(backup[i][j]) && backup[i][j] > '0') {
                    int u = size_n * size_n + i * size_n + j + 1;
                    cap[u][total_vertices - 1] = backup[i][j] - '0';
                    adj_list[u].add(total_vertices - 1);
                    adj_list[total_vertices - 1].add(u);
                }
            }
        }

        int total_flow_value = 0;
        int flow;
        while ((flow = max_flow()) != 0) {
            total_flow_value += flow;
        }

        System.out.println(total_flow_value);
    }
}
